record_usage: key model: model tokens: tokens
	| records |
	records := state at: 'records' ifAbsentPut: [ OrderedCollection new ].
	records add: (Dictionary new
		at: 'key' put: key;
		at: 'model' put: model;
		at: 'tokens' put: tokens;
		yourself).
	^ self usage: key

